 "content": "from collections import deque, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] != 0:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, x, y, x]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], y); b[1] = min(b[1], x)
                    b[2] = max(b[2], y); b[3] = max(b[3], x)
            layers = sorted(bounds, key=lambda color: (
                -((bounds[color][2] - bounds[color][0] + 1) * (bounds[color][3] - bounds[color][1] + 1)),
                -sum(1 for y, x in cells if grid[y][x] == color), color))
            mapping = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
